let navTools = nav.querySelector('.nav-tools');

  // Create the nav-tools section if it is missing. DA.live strips empty
  // divs during content processing, leaving nav with only 2 sections
  // (brand, sections) instead of 3 — without this guard header.js throws
  // "Cannot read properties of null".
  if (!navTools) {
    navTools = document.createElement('div');
    navTools.classList.add('nav-tools');
    nav.appendChild(navTools);
  }

const [product, labels] = await Promise.all([
  getProductData(true),
  fetchPlaceholders('placeholders/pdp.json'),
]);

// A published PDP whose SKU no longer resolves serves 200 from the content
// bus, so the CDN-404 redirect never runs. fetchProductData resolves null
// for an unknown SKU — send the shopper to the native 404 rather than
// mounting an empty product block. (Demo Builder warm-path guard.)
if (!product && !IS_UE) {
  return loadErrorPage();
}
